      {"unit_id":"u-3cd42c6b8097efa970da","start_line":1226,"end_line":1249,"role":"dependency","dependency_reason":"Declares distinct DTDVALID and NO_XXE option bits."}
    ]
  },
  "feasible_trigger": {
    "status": "established",
    "reason": "Four input bytes can encode both option bits, and the entity format can supply a main XML document with an internal DTD and SystemID. The supported option combination is therefore a finite input request before the target masks it.",
    "evidence": [
      {"unit_id":"u-3cd42c6b8097efa970da","start_line":1228,"end_line":1249,"role":"primary","dependency_reason":""},
