      {"unit_id":"u-d53af5f6d3f7aa8d6e48","start_line":310,"end_line":328,"role":"dependency","dependency_reason":"Shows how the first URL and entity become the main document."},
      {"unit_id":"u-2e80897a794d1b52f998","start_line":259,"end_line":287,"role":"dependency","dependency_reason":"Shows the literal backslash-n field delimiter and handling of trailing bytes."}
    ]
  },
  "observable_consequence": {
    "status": "established",
    "reason": "The target removes DTDVALID before the pull call. The pull API applies the supplied options, and the option setter enables validation only when DTDVALID is present. The documented validation mode cannot be requested through this route.",
    "evidence": [
      {"unit_id":"u-811c0b32cfdaac4ec677","start_line":13421,"end_line":13429,"role":"primary","dependency_reason":""},
      {"unit_id":"u-f2c7f848acfcfc4c1242","start_line":39,"end_line":59,"role":"primary","dependency_reason":""},
      {"unit_id":"u-571134570830cc1cf821","start_line":13351,"end_line":13355,"role":"dependency","dependency_reason":"Derives validation state specifically from DTDVALID; DTDLOAD and NOENT have separate effects."},
      {"unit_id":"u-62b8efdeec0de8e79a6a","start_line":13928,"end_line":13937,"role":"dependency","dependency_reason":"Applies the passed options before parsing the document."}
    ]
  },
  "alternatives_ruled_out": {
    "status": "established",
    "reason": "The complete target uses the same masked options for pull, push, and reader operations and makes no separate validation request. DTDLOAD and NOENT do not set the validation state.",
    "evidence": [
      {"unit_id":"u-f2c7f848acfcfc4c1242","start_line":30,"end_line":151,"role":"primary","dependency_reason":""},
      {"unit_id":"u-571134570830cc1cf821","start_line":13351,"end_line":13355,"role":"dependency","dependency_reason":"Shows that the other entity and DTD options do not substitute for DTDVALID."}
    ]
  },
